template:
fn to_u8(val: i32) -> Result<u8, &'static str> {
    let small: u8 = val
        .⟦slot1⟧
        .map_err(|_| "out of range")⟦slot2⟧;
    Ok(small)
}

fn main() {
    assert_eq!(to_u8(250), Ok(250));
    assert_eq!(to_u8(300), Err("out of range"));
}

tests:
#[test]
fn converts_valid() {
    assert_eq!(to_u8(0), Ok(0));
    assert_eq!(to_u8(255), Ok(255));
}
#[test]
fn rejects_out_of_bounds() {
    assert_eq!(to_u8(-1), Err("out of range"));
    assert_eq!(to_u8(256), Err("out of range"));
}
